import{_ as a}from"./chunks/image-006.BzaDFqgA.js";import{_ as p,o as t,c as _,a3 as o}from"./chunks/framework.DdpBa4_E.js";const f=JSON.parse('{"title":"第9章　有没有替代原因","description":"","frontmatter":{},"headers":[],"relativePath":"books/xuehui-tiwen/74-第9章-有没有替代原因.md","filePath":"books/xuehui-tiwen/74-第9章-有没有替代原因.md","lastUpdated":1794316978000}'),r={name:"books/xuehui-tiwen/74-第9章-有没有替代原因.md"};function s(i,e,n,l,c,d){return t(),_("div",null,[...e[0]||(e[0]=[o('<h1 id="第9章-有没有替代原因" tabindex="-1">第9章　有没有替代原因 <a class="header-anchor" href="#第9章-有没有替代原因" aria-label="Permalink to &quot;第9章　有没有替代原因&quot;">​</a></h1><p>学习目标</p><p>1）提高对替代原因普遍性的认识。</p><p>2）强化对如何发现替代原因的理解。</p><p>3）培养对混淆相关性和因果关系这一现象的频发和危险的敏感意识。</p><p>4）了解在讨论替代原因时，如何与他人有效互动。</p><p>我们以一个故事开始本章。</p><p>一个爱问为什么的孩子注意到太阳早上出现在天空，到夜里就不见了。孩子想知道太阳到底去哪儿了，于是想方设法地要凑近看看日落。可是，不管怎么努力，他还是不明白太阳到底去哪儿了。后来，孩子又注意到他的保姆也是早上出现在家里，到夜里就不见了。有一天，他好奇地问保姆，她晚上去哪儿了。保姆回答说：“我回家去了。”孩子将保姆的来去和日夜的循环联系在一起，得出结论：保姆的离去导致太阳也一起回家了。</p><p>这个故事清楚地表明了使用证据时一个常见的难题：试图弄明白一件事情的起因。我们只有理解引发某个现象的因果模式，才能选择一个明智的办法来避免问题的发生，或者促进某个特别正面的结果的出现。比如说，我们想知道是什么引起了2008年的金融危机。或者，为什么过去的十年里肥胖的比例会有如此急剧的上升。</p><p>这个故事同时还显示出在使用证据证明一件事引发另一件事时常见的一个难题，即替代原因（rival causes）的难题。那个虚构的小男孩为他观察到的问题提供了一个解释：“太阳晚上下山是因为我的保姆回家了。”他的“原因”好像很合理，并且能讲得通，但我们希望你能明白，还有一个对太阳为什么会落山更可靠的解释。</p><p>尽管替代原因很少会像在我们这个故事里表现得那样明显，但你经常会遇到专家提出一个假说来解释某件事或某个研究发现，而同时还有其他言之成理的假说同样能解释它们。通常情况下，专家不会把这些替代原因透露给你，因为他们不想让你分心，从而显得他们那些断言不那么确凿无疑，所以你得自己去发掘出这些替代原因。这样做特别有助于你判断“证据的效力怎么样”。有些事件存在着各种各样言之成理的替代原因，这就大大削弱了我们对写作者提供的原因的信心。</p><p>批判性问题：有没有替代原因？</p><p><img src="'+a+'" alt="" loading="lazy"></p><p>注意：所谓替代原因，即言之成理的替代解释，它能够说明为什么特定的结果会发生。</p>',14)])])}const h=p(r,[["render",s]]);export{f as __pageData,h as default};
